Шаг 2. Hello, Yandex. Или перечень устройств с их контролированием прямо на Вашем сайте
Управление через cron-скрипты — это отлично для фоновой автоматизации. Но что, если мы хотим зайти на сервер, увидеть актуальный статус всех 10+ устройств и вручную переключить розетку или изменить яркость лампы?
Писать для этого отдельный фронтенд на React/Vue и бэкенд на Laravel — избыточно. Мы пойдем путем элегантного минимализма:
один PHP-файл
, который работает как современное SPA-приложение (Single Page Application).
Работа с устройствами, интегрированными в Яндексе, через Ваш собственный скрипт на Вашем сервере
При разработке этого дашборда мы решили несколько нетривиальных инженерных задач, о которых стоит рассказать:
Оптимистичный интерфейс (Optimistic UI).
Облака умных домов работают с задержкой 1–3 секунды. Вместо того чтобы крутить спиннер и блокировать интерфейс, мы мгновенно переключаем тумблер в браузере. Если сервер вернет ошибку, мы так же мгновенно откатим состояние обратно. Пользователь видит отклик за 0 мс.
Параллельные запросы (
curl_multi
).
Стандартный последовательный опрос 10 устройств через API Яндекса занял бы 15–20 секунд. Мы используем
curl_multi_init
, чтобы опрашивать устройства, не ответившие на массовый запрос, параллельно. Это сокращает время загрузки до 2–3 секунд.
Борьба с блокировкой сессий PHP.
При асинхронных AJAX-запросах PHP блокирует файл сессии. Если один запрос "завис", остальные встанут в очередь. Решение: вызов
session_write_close()
сразу после чтения токена в API-роутере.
Null-safe парсинг.
API Яндекса иногда возвращает
null
вместо объекта состояния для новых или оффлайн-устройств. Жесткая проверка
onCap?.state
предотвращает падение JavaScript-кода с ошибкой
Cannot read properties of null
.
Готовый код дашборда (yandex_smarthome.php)
Создайте файл
yandex_smarthome.php
на вашем сервере и вставьте в него этот код. Не забудьте заменить
$CLIENT_ID
и
$CLIENT_SECRET
на ваши данные из консоли разработчика.
<?php
/**
 * Technofeya Home: Smart Dashboard (v9.6 - Production Ready)
 * Одностраничное приложение (SPA) для управления Яндекс.Умным домом.
 * Особенности: Optimistic UI, curl_multi, null-safe parsing, session lock fix.
 */
session_start();

// ==================== НАСТРОЙКИ ====================
// Вставьте сюда ваши реальные данные из консоли разработчика Яндекс
$CLIENT_ID = 'ВАШ_CLIENT_ID_ИЗ_КОНСОЛИ';
$CLIENT_SECRET = 'ВАШ_CLIENT_SECRET_ИЗ_КОНСОЛИ';
$REDIRECT_URI = 'https://oauth.yandex.ru/verification_code';
$API_BASE = 'https://api.iot.yandex.net/v1.0';
// ===================================================

function apiRequest($url, $method = 'GET', $data = null, $headers = []) {
 $ch = curl_init($url);
 curl_setopt_array($ch, [
 CURLOPT_RETURNTRANSFER => true,
 CURLOPT_HTTPHEADER => $headers,
 CURLOPT_TIMEOUT => 10,
 CURLOPT_SSL_VERIFYPEER => true,
 CURLOPT_FOLLOWLOCATION => true,
 ]);

 if ($method === 'POST') {
 curl_setopt($ch, CURLOPT_POST, true);
 if (!empty($data)) {
 if (strpos($url, 'oauth.yandex.ru') !== false) {
 curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
 } else {
 $headers = array_filter($headers, fn($h) => strpos($h, 'Content-Type') === false);
 $headers[] = 'Content-Type: application/json';
 curl_setopt($ch, CURLOPT_POSTFIELDS, is_array($data) ? json_encode($data) : $data);
 curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
 }
 }
 }

 $response = curl_exec($ch);
 $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
 curl_close($ch);

 $decoded = json_decode($response, true);
 return ['code' => $httpCode, 'body' => $decoded ?: ['raw_response' => $response]];
}

// Функция для параллельных запросов (ускоряет загрузку состояний в разы)
function apiRequestParallel($urls, $headers) {
 $mh = curl_multi_init();
 $curlArray = [];

 foreach ($urls as $key => $url) {
 $ch = curl_init($url);
 curl_setopt_array($ch, [
 CURLOPT_RETURNTRANSFER => true,
 CURLOPT_HTTPHEADER => $headers,
 CURLOPT_TIMEOUT => 10,
 CURLOPT_SSL_VERIFYPEER => true,
 ]);
 curl_multi_add_handle($mh, $ch);
 $curlArray[$key] = $ch;
 }

 $running = null;
 do { curl_multi_exec($mh, $running); } while ($running > 0);

 $results = [];
 foreach ($curlArray as $key => $ch) {
 $response = curl_multi_getcontent($ch);
 $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
 $decoded = json_decode($response, true);
 $results[$key] = ['code' => $httpCode, 'body' => $decoded ?: ['raw_response' => $response]];
 curl_multi_remove_handle($mh, $ch);
 }
 curl_multi_close($mh);
 return $results;
}

// ==================== API ROUTER (Обработка AJAX) ====================
if (isset($_GET['api']) && isset($_SESSION['yandex_token'])) {
 header('Content-Type: application/json');
 $token = $_SESSION['yandex_token'];

 // КРИТИЧЕСКИ ВАЖНО: снимаем блокировку сессии, чтобы параллельные AJAX-запросы не висели
 session_write_close();
 $iotHeaders = ["Authorization: Bearer {$token}"];

 if ($_GET['api'] === 'devices') {
 // 1. Получаем список устройств
 $infoRes = apiRequest("{$API_BASE}/user/info", 'GET', null, $iotHeaders);
 if ($infoRes['code'] !== 200 || !isset($infoRes['body']['devices'])) {
 echo json_encode(['error' => 'Не удалось получить список устройств', 'details' => $infoRes['body']]);
 exit;
 }

 $devices = $infoRes['body']['devices'];
 $deviceIds = array_map(fn($d) => ['id' => $d['id']], $devices);

 // 2. Пробуем быстрый массовый запрос состояний
 $queryRes = apiRequest("{$API_BASE}/user/devices/query", 'POST', ['devices' => $deviceIds], $iotHeaders);
 $states = [];

 if ($queryRes['code'] === 200 && isset($queryRes['body']['devices'])) {
 foreach ($queryRes['body']['devices'] as $devState) {
 $states[$devState['id']] = $devState['capabilities'] ?? [];
 }
 }

 // 3. Fallback: запрашиваем параллельно только те устройства, где нет состояния
 $missing = array_filter($devices, fn($d) => !isset($states[$d['id']]));
 if (count($missing) > 0) {
 $urls = array_map(fn($d) => "{$API_BASE}/devices/{$d['id']}", $missing);
 $parallelRes = apiRequestParallel($urls, $iotHeaders);

 foreach ($parallelRes as $key => $res) {
 if ($res['code'] === 200 && isset($res['body']['capabilities'])) {
 $devId = $missing[$key]['id'];
 $states[$devId] = $res['body']['capabilities'];
 $devices[array_search($devId, array_column($devices, 'id'))]['device_state'] = $res['body']['state'] ?? 'unknown';
 }
 }
 }

 // 4. Объединяем данные для фронтенда
 foreach ($devices as &$dev) {
 $dev['current_state'] = $states[$dev['id']] ?? [];
 if (!isset($dev['device_state'])) {
 $dev['device_state'] = 'unknown';
 }
 }

 echo json_encode(['success' => true, 'devices' => $devices]);
 exit;
 }

 if ($_GET['api'] === 'action') {
 $rawInput = file_get_contents('php://input');
 $input = json_decode($rawInput, true) ?: $_POST;

 if (empty($input) || !isset($input['devices'])) {
 echo json_encode(['success' => false, 'error' => 'Пустые данные']);
 exit;
 }

 $res = apiRequest("{$API_BASE}/devices/actions", 'POST', $input, $iotHeaders);
 if ($res['code'] === 200 || $res['code'] === 202) {
 echo json_encode(['success' => true]);
 } else {
 echo json_encode(['success' => false, 'error' => "HTTP {$res['code']}", 'details' => $res['body']]);
 }
 exit;
 }
}

// ==================== ЛОГИКА АВТОРИЗАЦИИ ====================
if (isset($_POST['manual_code']) && !isset($_SESSION['yandex_token'])) {
 $res = apiRequest('https://oauth.yandex.ru/token', 'POST', [
 'grant_type' => 'authorization_code', 'code' => trim($_POST['manual_code']),
 'client_id' => $CLIENT_ID, 'client_secret' => $CLIENT_SECRET, 'redirect_uri' => $REDIRECT_URI
 ]);

 if ($res['code'] == 200 && isset($res['body']['access_token'])) {
 $_SESSION['yandex_token'] = $res['body']['access_token'];
 $userInfo = apiRequest('https://login.yandex.ru/info?format=json', 'GET', null, ['Authorization: OAuth ' . $_SESSION['yandex_token']]);
 $_SESSION['yandex_user'] = $userInfo['body']['login'] ?? 'User';
 header('Location: ' . strtok($_SERVER["REQUEST_URI"], '?'));
 exit;
 }
 $authError = "Ошибка авторизации: " . json_encode($res['body']);
}

if (!isset($_SESSION['yandex_token'])) {
 $authUrl = "https://oauth.yandex.ru/authorize?response_type=code&client_id={$CLIENT_ID}&redirect_uri=" . urlencode($REDIRECT_URI);
