 <script>
 async function loadDevices() {
 const grid = document.getElementById('devices-grid');
 const btn = document.getElementById('refresh-icon');
 btn.classList.add('animate-spin');

 try {
 const res = await fetch('?api=devices');
 const data = await res.json();

 if (data.error) {
 grid.innerHTML = `<div class="col-span-full bg-red-100 text-red-700 p-4 rounded-lg border border-red-200">${data.error}</div>`;
 return;
 }

 grid.innerHTML = '';
 if (!data.devices || data.devices.length === 0) {
 grid.innerHTML = `<div class="col-span-full text-center text-gray-500 py-10">Устройства не найдены.</div>`;
 return;
 }

 data.devices.forEach(dev => grid.appendChild(createDeviceCard(dev)));
 showToast('✅ Список обновлен');
 } catch (e) {
 grid.innerHTML = `<div class="col-span-full bg-red-100 text-red-700 p-4 rounded-lg">Ошибка сети: ${e.message}</div>`;
 } finally {
 btn.classList.remove('animate-spin');
 }
 }

 function createDeviceCard(dev) {
 const state = dev.current_state || [];
 const onCap = state.find(c => c.type === 'devices.capabilities.on_off');

 // NULL-SAFE: безопасно извлекаем данные, даже если Яндекс вернул null
 const capState = onCap?.state || {}; 
 const isRetrievable = onCap ? onCap.retrievable : false;
 const isOn = isRetrievable ? !!capState.value : false;
 const lastUpdated = isRetrievable && capState.last_updated ? capState.last_updated : 0;
 const isStale = lastUpdated > 0 && (Date.now() / 1000 - lastUpdated) > 3600; // Старше 1 часа

 const deviceState = dev.device_state || 'unknown';
 const isOffline = deviceState === 'offline';

 let statusBadge = '';
 if (isOffline) {
 statusBadge = `<span class="text-[10px] bg-gray-200 text-gray-600 px-2 py-0.5 rounded-full">📡 Не в сети</span>`;
 } else if (isStale) {
 statusBadge = `<span class="text-[10px] bg-yellow-100 text-yellow-700 px-2 py-0.5 rounded-full" title="Статус не обновлялся более часа">⚠️ Устаревшие данные</span>`;
 } else if (!isRetrievable) {
 statusBadge = `<span class="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full" title="Устройство не сообщает свой статус">❓ Статус неизвестен</span>`;
 }

 let extraControls = '';
 const rangeCap = state.find(c => c.type === 'devices.capabilities.range');
 if (rangeCap && rangeCap.retrievable && rangeCap?.state) {
 const val = rangeCap.state.value;
 const min = rangeCap.parameters?.range?.min || 1;
 const max = rangeCap.parameters?.range?.max || 100;
 const instance = rangeCap.state.instance;
 const label = instance === 'brightness' ? 'Яркость' : (instance === 'temperature' ? 'Температура' : 'Уровень');

 extraControls += `
 <div class="mt-4 pt-4 border-t border-gray-100">
 <div class="flex justify-between text-xs text-gray-500 mb-1">
 <span>${label}</span>
 <span id="val-${dev.id}-${instance}" class="font-bold text-blue-600">${val}</span>
 </div>
 <input type="range" min="${min}" max="${max}" value="${val}" 
 class="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-500"
 onchange="sendRangeAction('${dev.id}', '${instance}', this.value)" ${isOffline ? 'disabled' : ''}>
 </div>
 `;
 }

 const card = document.createElement('div');
 card.id = `card-${dev.id}`;
 card.className = `glass-panel rounded-2xl p-5 shadow-sm border border-white/60 hover:shadow-md transition relative overflow-hidden ${isOffline ? 'opacity-75' : ''}`;
 card.innerHTML = `
 <div class="absolute top-0 right-0 w-24 h-24 bg-gradient-to-br from-blue-50 to-transparent rounded-bl-full -mr-4 -mt-4"></div>
 <div class="relative z-10">
 <div class="flex justify-between items-start mb-2">
 <div>
 <h3 class="font-bold text-lg text-gray-800 leading-tight flex items-center gap-2">
 ${dev.name}
 ${statusBadge}
 </h3>
 <p class="text-[10px] text-gray-400 mt-1 font-mono truncate w-40" title="${dev.id}">${dev.id}</p>
 </div>
 <div id="status-${dev.id}" class="status-indicator w-3 h-3 rounded-full mt-1.5 ${isOn ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-gray-300'}"></div>
 </div>

 <div class="flex items-center justify-between mt-4">
 <span id="text-${dev.id}" class="text-sm font-medium ${isOn ? 'text-green-600' : 'text-gray-400'}">
 ${isOn ? 'Включено' : (isRetrievable ? 'Выключено' : 'Статус неизвестен')}
 </span>

 <label class="relative inline-flex items-center cursor-pointer ${isOffline ? 'opacity-50 cursor-not-allowed' : ''}">
 <input type="checkbox" id="toggle-${dev.id}" class="sr-only toggle-checkbox" ${isOn ? 'checked' : ''} 
 onchange="sendOnOffAction('${dev.id}', this.checked)" ${isOffline ? 'disabled' : ''}>
 <div class="w-11 h-6 bg-gray-200 rounded-full toggle-label transition-colors duration-300"></div>
 <div id="knob-${dev.id}" class="absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform duration-300 transform ${isOn ? 'translate-x-5' : 'translate-x-0'} shadow-sm"></div>
 </label>
 </div>
 ${extraControls}
 </div>
 `;
 return card;
 }

 // Мгновенное обновление интерфейса до ответа сервера (Optimistic UI)
 function updateDeviceUI(deviceId, isOn) {
 const status = document.getElementById(`status-${deviceId}`);
 const text = document.getElementById(`text-${deviceId}`);
 const toggle = document.getElementById(`toggle-${deviceId}`);
 const knob = document.getElementById(`knob-${deviceId}`);

 if (status) status.className = `status-indicator w-3 h-3 rounded-full mt-1.5 ${isOn ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-gray-300'}`;
 if (text) {
 text.className = `text-sm font-medium ${isOn ? 'text-green-600' : 'text-gray-400'}`;
 text.textContent = isOn ? 'Включено' : 'Выключено';
 }
 if (toggle) toggle.checked = isOn;
 if (knob) knob.className = `absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform duration-300 transform ${isOn ? 'translate-x-5' : 'translate-x-0'} shadow-sm`;
 }

 async function sendAction(deviceId, payload, optimisticUpdate = null) {
 showToast('⏳ Отправка команды...', 'info');
 if (optimisticUpdate !== null) updateDeviceUI(deviceId, optimisticUpdate);

 try {
 const res = await fetch('?api=action', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({devices: [{id: deviceId, actions: [payload]}]})
 });
 const data = await res.json();

 if (data.success) {
 showToast('✅ Команда выполнена');
 // Фоновая синхронизация через 5 секунд, когда облако реально обновит статус
 setTimeout(loadDevices, 5000);
 } else {
 showToast('❌ ' + (data.error || 'Ошибка') + (data.details ? ': ' + JSON.stringify(data.details) : ''), 'error');
 // Откат интерфейса при ошибке
 if (optimisticUpdate !== null) updateDeviceUI(deviceId, !optimisticUpdate);
 }
 } catch (e) {
 showToast('❌ Ошибка сети: ' + e.message, 'error');
 if (optimisticUpdate !== null) updateDeviceUI(deviceId, !optimisticUpdate);
 }
 }

 function sendOnOffAction(deviceId, isOn) {
 sendAction(deviceId, {type: 'devices.capabilities.on_off', state: {instance: 'on', value: isOn}}, isOn);
 }

 function sendRangeAction(deviceId, instance, value) {
 const el = document.getElementById(`val-${deviceId}-${instance}`);
 if (el) el.innerText = value;
 sendAction(deviceId, {type: 'devices.capabilities.range', state: {instance: instance, value: parseInt(value)}});
 }

 function showToast(msg, type = 'success') {
 const toast = document.getElementById('toast');
 toast.innerText = msg;
 toast.className = `fixed bottom-5 right-5 px-6 py-3 rounded-lg shadow-xl transform transition-all duration-300 z-50 text-white text-sm ${type === 'error' ? 'bg-red-500' : (type === 'info' ? 'bg-gray-600' : 'bg-green-600')}`;
 toast.style.transform = 'translateY(0)';
 toast.style.opacity = '1';
 setTimeout(() => {
 toast.style.transform = 'translateY(20px)';
 toast.style.opacity = '0';
 }, 4000);
 }

 document.addEventListener('DOMContentLoaded', loadDevices);
 </script>
</body>
</html>
Как это работает:
При первом запуске скрипт покажет форму для ввода кода авторизации Яндекса.
После успешного входа вы увидите сетку карточек всех ваших устройств.
Нажмите на переключатель любой розетки. Интерфейс переключится
мгновенно
(благодаря Optimistic UI), команда уйдет на сервер, а через 5 секунд произойдет тихая фоновая синхронизация для подтверждения реального статуса.
Если устройство оффлайн, карточка станет полупрозрачной, а переключатель заблокируется, чтобы не вводить вас в заблуждение.
Этот код полностью автономен, не требует сборщиков (Webpack/Vite) или баз данных, и готов к работе сразу после загрузки на хостинг.
Шаг 3. Магия простых HTTP-запросов
Вся интеграция строится на двух вещах:
Мы забираем данные с нашего датчика через простой GET-запрос.
Мы отправляем команду в Яндекс через POST-запрос с JSON-телом.
Вот как выглядит наш источник данных с Sensorbox. Обратите внимание, он отдает чистый JSON:
https://iot.tfeya.ru/sensorData.php?login=eugene&sensor_id=1&secret=001c0ee0805bd121xxxxxxxxxxxxxeb9ad576&json=1
Ответ:
{"val":"50","datetime":"2026-05-30 23:06:01"}
(Для примера значение
50
означает критическую сухость).
Шаг 4. Пример автоматизации полива (PHP)
Ниже представлен минималистичный, но полнофункциональный скрипт
auto_watering.php
. Он делает ровно то, что мы задумали: проверяет датчик (для простоты не усложняем, но суть Вы понимаете), принимает решение и дергает розетку Яндекса.
<?php
/**
 * auto_watering.php - Гибридный контроллер умного дома
 */

// === НАСТРОЙКИ ===
$YANDEX_TOKEN = 'ВАШ_OAUTH_TOKEN_ЗДЕСЬ'; // Получается через OAuth
$DEVICE_ID = '19aae231-xxxxx-xxxx-.....'; // ID розетки из приложения Яндекс
$SENSOR_URL = 'https://iot.tfeya.ru/sensorData.php?login=eugene&sensor_id=1&secret=00xxxxxxxx121cba99c83eec54f0f43a0eeeb9ad576&json=1';
$DRY_THRESHOLD = 15; // Порог влажности, ниже которого включаем полив (%)

// 1. Получаем данные с нашего кастомного датчика
$sensorDataJson = file_get_contents($SENSOR_URL);
$sensorData = json_decode($sensorDataJson, true);

if (!$sensorData || !isset($sensorData['val'])) {
 die("Ошибка: Не удалось получить данные с Sensorbox");
}

$currentMoisture = (int)$sensorData['val'];
echo "Текущая влажность: {$currentMoisture}%\n";

// 2. Логика принятия решения (здесь можно добавить усреднение, гистерезис и т.д.)
$shouldWater = ($currentMoisture < $DRY_THRESHOLD);

// 3. Формируем команду для Яндекс.Умного дома
// Документация: https://yandex.ru/dev/dialogs/smart-home/doc/ru/concepts/control-api
$payload = [
 "devices" => [[
 "id" => $DEVICE_ID,
 "actions" => [[
 "type" => "devices.capabilities.on_off",
 "state" => [
 "instance" => "on",
 "value" => $shouldWater // true или false
 ]
 ]]
 ]]
];

// 4. Отправляем запрос в Яндекс
$ch = curl_init('https://api.iot.yandex.net/v1.0/devices/actions');
curl_setopt_array($ch, [
 CURLOPT_RETURNTRANSFER => true,
 CURLOPT_POST => true,
 CURLOPT_POSTFIELDS => json_encode($payload),
 CURLOPT_HTTPHEADER => [
 'Authorization: Bearer ' . $YANDEX_TOKEN,
 'Content-Type: application/json'
 ],
 CURLOPT_TIMEOUT => 10
]);

$response = curl_exec($ch);
$httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
curl_close($ch);

// 5. Вывод результата
if ($httpCode === 200 || $httpCode === 202) {
 $actionText = $shouldWater ? "ВКЛЮЧЕН (полив)" : "ВЫКЛЮЧЕН (достаточно влаги)";
 echo "✅ Успех! Розетка Яндекс {$actionText}.\n";
} else {
 echo "❌ Ошибка API Яндекса (HTTP {$httpCode}): {$response}\n";
}
?>
Как это использовать?
Загружаете этот файл на свой сервер (например,
iot.tfeya.ru
).
Настраиваете
Cron
на выполнение этого скрипта, например, каждые 30 минут:
*/30 * * * * /usr/bin/php /var/www/iot.tfeya.ru/auto_watering.php >> /var/log/watering.log
Всё. Ваш кастомный датчик теперь управляет коммерческой экосистемой.
А что насчет красивого интерфейса?
Управление через cron — это хорошо для автоматизации, но иногда хочется зайти и проверить состояние вручную, или увидеть список всех устройств. Но если в приложении Яндекса это можно сделать тольно по правилам игры разработчиков самого Яндекса, то на Вашей странице открывается полная свобода действий. И полная свобода по дизайну итогового решения, с которым Вы хотите встречаться дальше при дальнейшем совершенствовании Вашего Умного Дома.
Выше показано, в процессе работы над этой задачей был создан полноценный
SPA-дашборд на PHP + Tailwind CSS
(в одном файле), который:
Проходит OAuth-авторизацию Яндекса.
Мгновенно (без перезагрузки страницы) показывает статус всех устройств (используя
curl_multi
для параллельных запросов, чтобы не ждать ответа 10 секунд).
Позволяет включать/выключать приборы, менять яркость ламп и температуру обогревателей.
Корректно обрабатывает состояния
offline
и
retrievable: false
, не вводя пользователя в заблуждение.
Код дашборда получился довольно объемным для статьи, но он полностью готов к использованию. Если тема будет интересна сообществу, я с радостью выложу его в отдельном репозитории на GitHub или в следующей статье.
(Спойлер: ключ к стабильности такого дашборда — использование
session_write_close()
перед AJAX-запросами в PHP и "оптимистичное" обновление UI на стороне JavaScript, о чем можно почитать в материалах по архитектуре современных веб-приложений).
Почему это лучше, чем «просто купить всё готовое»?
Свобода логики.
Вы не ограничены визуальным конструктором сценариев Яндекса. Хотите включить свет, если влажность < 20%, И на улице темно (данные с открытого Weather API), И сегодня не вторник? На PHP это 5 строчек кода.
Объединение экосистем.
На одном дашборде могут быть устройства Яндекса, датчики Sensorbox, камеры Xiaomi и реле, управляемые через MQTT. Ваш сервер — это универсальный переводчик.
Независимость.
Если завтра Яндекс изменит правила бесплатных сценариев или отключит серверы, ваша базовая логика автоматизации останется на вашем сервере и продолжит работать.
Это просто.
Как мы видели выше, интеграция сводится к двум функциям:
file_get_contents()
для чтения и
curl
для записи. Никаких сложных брокеров сообщений или Docker-контейнеров для базовой задачи не требуется.
Заключение
Не стоит воспринимать DIY и готовые экосистемы как врагов. Они идеально дополняют друг друга. Яндекс дает надежное, сертифицированное и безопасное "железо" (розетки, реле), а ваш собственный сервер дает интеллект, гибкость и контроль над данными.
Попробуйте написать такой «мост». Вы удивитесь, насколько мощным может стать ваш умный дом, когда вы перестанете быть просто пользователем и станете его архитектором.
